function saveLanguageCookie(value){document.cookie='nodeno_language='+encodeURIComponent(value)+'; Path=/; Max-Age=31536000; SameSite=Lax'+(location.protocol==='https:'?'; Secure':'');}
function renderShell(){document.documentElement.dataset.market=visitor.international?'international':visitor.country==='TR'?'domestic':'unknown';document.documentElement.lang=locale;document.documentElement.dir=localeMetadata[locale].direction;document.title=`NODENO — ${t('slogan')}`;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));document.querySelectorAll('[data-label]').forEach(el=>el.setAttribute('aria-label',t(el.dataset.label)));document.querySelectorAll('[data-placeholder]').forEach(el=>el.placeholder=t(el.dataset.placeholder));$('#language').innerHTML=Object.entries(localeMetadata).map(([key,m])=>`<option value="${key}">${m.nativeName}</option>`).join('');$('#language').value=locale;document.querySelector('.language-current').textContent=localeMetadata[locale].short;$('#root-links').innerHTML=rootCategories().filter(c=>categoryCount(c.id)).slice(0,7).map(c=>`<a href="${esc(href('catalog',{category:c.id}))}" data-nav>${esc(loc(c.name))}</a>`).join('');$('#account-menu').innerHTML=sessionStatus==='error'?`<p class="subtle">${esc(t('sessionUnavailable'))}</p><button class="button" data-action="retry-account">${esc(t('retry'))}</button>`:sessionStatus==='loading'?`<p role="status">${esc(t('loading'))}</p>`:session.user?`<strong>${esc(session.user.name)}</strong>${['account','orders','addresses','shipping','favorites','collections','recent'].map(page=>navLink(page,page)).join('')}<button class="link-button" data-action="logout">${esc(t('logout'))}</button>`:`${navLink('login','login','button button-dark')}${navLink('register','register','button')}${navLink('orders','orders')}${navLink('help','help')}`;doorUI?.toolbar();$('#footer').innerHTML=`<div class="wrap"><div class="footer-grid"><div><a class="footer-logo" href="${href()}" data-nav><img src="/assets/brand/logo-horizontal.svg?v=social-keywords-20261113-v6" width="1600" height="360" alt="NODENO"></a><p>${esc(t('slogan'))}</p>${config.checkoutEnabled?'':`<p class="subtle">${esc(t('catalogueMode'))}</p>`}${config.parentCompany?.statement?`<p class="parent-company">${esc(loc(config.parentCompany.statement))}</p>`:''}</div><nav><h2>${esc(t('discover'))}</h2>${navLink('catalog','allProducts')}${navLink('favorites','favorites')}${navLink('collections','collections')}${navLink('compare','compare')}${navLink('recent','recent')}${navLink('account','account')}<a href="${esc(href('sets'))}" data-nav data-furniture-nav>Takımını oluştur</a><a href="${esc(href('wholesale'))}" data-nav data-wholesale-nav data-wholesale-only>Yurt dışı toplu alım</a></nav><nav><h2>${esc(t('assistance'))}</h2>${navLink('help','help')}${navLink('shipping','shipping')}${navLink('help','returns','',{section:'returns'})}${legalLinks(locale)}</nav><div class="footer-contact"><h2>${esc(t('contact'))}</h2>${contactMarkup()}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} NODENO. ${esc(t('rights'))}</span><a href="#page">${esc(t('backTop'))}</a><a class="geo-attribution" href="https://db-ip.com" rel="noopener noreferrer" target="_blank">IP Geolocation by DB-IP</a></div></div>`;$('#bottom-nav').innerHTML=[['home','home','home'],['categories','categories','menu'],['favorites','favorites','heart'],['cart','cart','cart'],['account','account','user']].map(([page,label,ico])=>`<a href="${esc(href(page))}" data-nav ${(currentRoute().page===page||page==='categories'&&currentRoute().page==='catalog')?'aria-current="page"':''}>${icon(ico)}<span>${esc(t(label))}</span>${page==='cart'?'<b class="count-badge" data-bottom-count></b>':''}</a>`).join('');renderMega();updateCounts();}
function historyView(state){const value=state?.nodenoView;return{key:Number.isSafeInteger(value?.key)&&value.key>0?value.key:++nextViewKey,limit:Number.isFinite(value?.limit)?Math.max(24,Math.min(10000,Math.trunc(value.limit))):24,scrollY:Number.isFinite(value?.scrollY)?Math.max(0,Math.min(1000000,Math.round(value.scrollY))):0};}
function captureView(){return{key:activeViewKey,limit:Math.max(24,Math.min(10000,limit)),scrollY:Math.max(0,Math.min(1000000,Math.round(restoringView?.token===viewRestoreToken?restoringView.scrollY:window.scrollY)))};}
function rememberView(view){viewCache.delete(view.key);viewCache.set(view.key,view);if(viewCache.size>32)viewCache.delete(viewCache.keys().next().value);}
function saveView(){clearTimeout(viewSaveTimer);viewSaveTimer=null;const view=captureView(),previous=history.state?.nodenoView;rememberView(view);if(previous?.key===view.key&&previous?.limit===view.limit&&previous?.scrollY===view.scrollY)return;history.replaceState({nodenoView:view},'');}
function applyViewRestore(){if(!pendingViewRestore||catalogStatus!=='ready')return;const view=pendingViewRestore;pendingViewRestore=null;requestAnimationFrame(()=>{if(view.token===viewRestoreToken){window.scrollTo({left:0,top:view.scrollY,left:0,behavior:'instant'});restoringView=null;}});}
function restoreView(state){clearTimeout(viewSaveTimer);viewSaveTimer=null;const stored=historyView(state),view=viewCache.get(stored.key)||stored;activeViewKey=view.key;nextViewKey=Math.max(nextViewKey,activeViewKey);limit=view.limit;pendingViewRestore={...view,token:++viewRestoreToken};restoringView=pendingViewRestore;applyViewRestore();}
async function navigate(url,{replace=false,focus=true}={}){const target=new URL(url,location.origin);if(target.origin!==location.origin)return;const nextLocale=target.searchParams.get('lang');if(locales.includes(nextLocale)&&nextLocale!==locale){const request=++localeRequest;try{await ensureLocale(nextLocale);}catch{toast(t('errorTitle'));return;}if(request!==localeRequest)return;locale=nextLocale;localizeDataTree(catalog,locale);localizeDataTree(config,locale);doorUI?.setLocale(locale);write('nodeno.language.v1',locale);saveLanguageCookie(locale);}saveView();viewRestoreToken++;pendingViewRestore=null;restoringView=null;closePanels();document.querySelectorAll('dialog[open]').forEach(d=>d.close());activeViewKey=++nextViewKey;history[replace?'replaceState':'pushState']({nodenoView:{key:activeViewKey,limit:24,scrollY:0}},'',target.pathname+target.search+target.hash);const next=target.searchParams.get('lang');if(locales.includes(next))locale=next;limit=24;renderShell();renderPage({focus});window.scrollTo({left:0,top:0,left:0,behavior:'instant'});}
function empty(title,body='',kind='box'){return`<div class="empty-state"><span class="empty-icon">${icon(kind)}</span><h2>${esc(t(title))}</h2>${body?`<p>${esc(t(body))}</p>`:''}${navLink('catalog','browse','button button-dark')}</div>`;}
function pageHeading(key,extra='',title=''){return`<header class="page-heading"><div><p class="breadcrumb">${navLink('home','home')} <span class="breadcrumb-separator" aria-hidden="true"></span> ${esc(t(key))}</p><h1 tabindex="-1">${esc(title||t(key))}</h1></div>${extra}</header>`;}
function priceMarkup(p,cls='product-price',compact=false){const minor=isDoor(p)&&currentRoute().page==='product'&&currentRoute().product===p.id?measurementsUI.basePrice(p):unitPriceMinor(p);if(minor===null)return esc(t('onRequest'));const unit=isCabinetFront(p)&&!p.configuredFront?' / m²':'';const current=`${compact?'<span class="card-price-main">':''}<bdi class="${esc(cls)}" data-price="${esc(p.id)}" dir="auto">${esc(formatMoney(minor,locale))}</bdi>${compact&&unit?`<span class="price-unit">${unit.trim()}</span>`:""}${compact?"</span>":""}<small class="price-tax-note">${esc(isSupplierProduct(p)?[supplierPriceSuffix(p,locale).trim(),supplierTaxNote(p,locale)].filter(Boolean).join('  '):paymentText(locale,'netLabel'))}</small>`,discount=discountInfo(p);if(!discount)return current+(compact?'':unit);const badge=formatDiscount(discount.discountPercent,locale);return`<span class="price-comparison"><span class="price-before"><span class="price-caption">${esc(t('previousPrice'))}</span><s><bdi data-previous-price="${esc(p.id)}" dir="auto">${esc(formatMoney(discount.previousPriceMinor,locale))}</bdi></s></span><span class="price-now"><span class="sr-only">${esc(t('salePrice'))}: </span>${current}${badge?`<span class="price-discount">${esc(badge)}</span>`:''}</span></span>`;}
function linePriceMarkup(p,quantity){const minor=unitPriceMinor(p);return minor===null?'':`<p class="basket-line-total"><span>${esc(t('lineTotal'))}</span><bdi dir="auto">${esc(formatMoney(p.calculatedLineTotal??minor*quantity,locale))}</bdi></p>`;}
function basketMoneySummary(){const sum=cartPrices(selectedCart(),catalog.products),subtotal=sum.quantity===0?0:sum.subtotalMinor;return`<dl><div><dt>${esc(t('selected'))}</dt><dd>${count(sum.quantity)} ${esc(t('items'))}</dd></div><div class="summary-subtotal"><dt>${esc(t(sum.unpricedCount?'pricedSubtotal':'subtotal'))}</dt><dd>${subtotal===null?esc(t('notPriced')):`<bdi dir="auto">${esc(formatMoney(subtotal,locale))}</bdi>`}</dd></div></dl>${sum.unpricedCount?`<p class="price-missing-notice">${esc(t('missingPriceNotice'))}</p>`:''}`;}
function cardVariantMarkup(p){const variants=variantsOf(p);if(isSupplierProduct(p))return variants.length>1?`<p class="card-color">${esc(supplierOptionCount(variants.filter(v=>!v.variationSelectionRequired).length,locale))}</p>`:'';return variants.length>1?`<div class="card-variants" aria-label="${esc(t('colorOptions'))}">${variants.slice(0,variants.length>4?3:4).map(v=>productLink(v.id,image(v,v.coverIndex||0,{alt:loc(v.variantColor)}),'card-variant')).join('')}${variants.length>4?productLink(p.id,esc(count(variants.length)+' '+t('colorOptions')),'card-variant-more'):''}</div>`:'';}
function homeRooms(){const roots=rootCategories().filter(c=>categoryCount(c.id)),preferred=['yatak-odasi','calisma-odalari','salon-ve-oturma-odasi'],rooms=[...preferred.map(id=>roots.find(c=>c.id===id)).filter(Boolean),...roots].filter((c,i,all)=>all.findIndex(v=>v.id===c.id)===i).slice(0,3);return`<section class="room-stories"><div class="section-heading"><div><p class="eyebrow">NODENO</p><h2>${esc(t('roomsTitle'))}</h2></div>${navLink('categories','allCategories','text-link')}</div><div class="room-story-grid">${rooms.map(c=>{const p=categoryPhoto(c.id);return`<a class="room-story" href="${esc(href('catalog',{category:c.id}))}" data-nav>${p?image(p,p.coverIndex||0,{alt:''}):''}<div><h3>${esc(loc(c.name))}</h3><p>${count(categoryCount(c.id))} ${esc(t('categoryProducts'))}</p></div></a>`;}).join('')}</div></section>`;}
function productServicePanel(p){const phone=contactLinks(config).find(link=>link.kind==='phone'),suggestions=productSuggestions(p,catalog.products,catalog.categories,recent);return `<aside class="product-service-panel" aria-label="${esc(t('productSupport'))}">
 <nav class="product-related-nav" aria-label="${esc(t('productRecommendations'))}">${suggestions.similar.length?`<a href="#product-shelf-productSimilar" data-specs-link>${esc(t('productSimilar'))}</a>`:''}${suggestions.complementary.length?`<a href="#product-shelf-productComplementary" data-specs-link>${esc(t('productComplementary'))}</a>`:''}</nav>
 <section class="service-store"><a class="service-brand" href="${esc(href('catalog'))}" data-nav translate="no">NODENO</a>${navLink('catalog','allProducts','text-link')}<nav class="service-guides" aria-label="${esc(t('shoppingInformation'))}">${navLink('shipping','shipping','text-link')}${navLink('help','returns','text-link',{section:'returns'})}<a href="#product-faq" data-specs-link>${esc(t('productFaq'))}</a></nav><div class="service-contact"><h2>${esc(t('productSupport'))}</h2>${phone?`<a class="service-phone" href="${esc(phone.href)}">${esc(config.brand?.contact?.phone||config.contact?.phone||'0850 305 84 78')}</a>`:''}${navLink('help','help','text-link')}</div></section>
 </aside>`;}

function cartSuggestions(){const first=byId(cart[0]?.id);if(!first)return'';const ids=new Set(cart.map(cartLineKey)),suggestions=productSuggestions(first,catalog.products,catalog.categories).similar.filter(p=>!ids.has(p.id));return suggestions.length?`<div class="desktop-cart-shelf">${productShelf('cartSuggestions',suggestions)}</div>`:'';}
function productCard(p){const isSaved=saved.has(p.id);return`<article class="product-card"><div class="product-card-stage">${productLink(p.id,image(p),'product-stage')}${experience?.quickButton(p)||''}<button class="product-save ${isSaved?'saved':''}" type="button" data-save="${esc(p.id)}" aria-label="${esc(t('favorites'))}: ${esc(productName(p))}" aria-pressed="${isSaved}">${icon('heart')}</button></div><div class="product-info"><h3>${productLink(p.id,esc(productName(p)))}</h3>${cardVariantMarkup(p)}${!isSupplierProduct(p)&&p.variantColor?`<p class="card-color">${esc(loc(p.variantColor))}${variantsOf(p).length>1?` · ${count(variantsOf(p).length)} ${esc(t('colorOptions'))}`:''}</p>`:''}<p class="pricing-note card-price-compact">${priceMarkup(p,'product-price',true)}</p><button class="button card-add" data-add="${esc(p.id)}">${icon('cart')}<span>${esc(t('add'))}</span></button>${experience?.cardTools(p)||''}</div></article>`;}
