function sortSelect(id,sort){return`<label class="sort-field" for="${id}"><span>${esc(t('sort'))}</span><select id="${id}" data-sort>${sortOptions(sort)}</select></label>`;}
function sortOptions(sort){return ['recommended','price-asc','price-desc','name-asc','name-desc'].map((value,i)=>`<option value="${value}" ${value===sort?'selected':''}>${esc(t(['recommended','priceLowHigh','priceHighLow','nameAsc','nameDesc'][i]))}</option>`).join('');}
function catalogParams(overrides={}){const {category,q,sort,minPrice,maxPrice,color,maxWidth,maxHeight,maxDepth}=currentRoute();return{category,q,sort,minPrice,maxPrice,color,maxWidth,maxHeight,maxDepth,...overrides};}
function catalogColors(){const route=currentRoute(),items=filterProducts(catalog.products,{query:route.q,category:route.category,categories:catalog.categories,locale});const seen=new Set();return items.filter(p=>p.variantColor?.tr&&!p.colorReviewPending&&!seen.has(p.variantColor.tr)&&seen.add(p.variantColor.tr)).sort((a,b)=>loc(a.variantColor).localeCompare(loc(b.variantColor),locale));}
function activeFilterMarkup(){const route=currentRoute(),entries=[];if(route.category)entries.push([loc(categoryById(route.category)?.name)||route.category,{category:''}]);if(route.color){const product=catalog.products.find(p=>p.variantColor?.tr===route.color);entries.push([product?loc(product.variantColor):route.color,{color:''}]);}for(const [key,label] of [['minPrice','minimumPrice'],['maxPrice','maximumPrice']]){const value=priceFilterMinor(route[key]);if(value!==null)entries.push([t(label)+': '+formatMoney(value,locale),{[key]:''}]);}for(const axis of ['Width','Height','Depth'])if(parseSpaceMeasure(route['max'+axis])!==null)entries.push([t('dimension'+axis)+': '+route['max'+axis]+' cm',{['max'+axis]:''}]);return entries.length?`<div class="active-filters" aria-label="${esc(t('activeFilters'))}">${entries.map(([label,reset])=>`<a href="${esc(href('catalog',catalogParams(reset)))}" data-nav aria-label="${esc(t('removeFilter')+': '+label)}">${esc(label)}${icon('close')}</a>`).join('')}</div>`:'';}
function categoryShortcuts(){const route=currentRoute(),children=catalog.categories.filter(c=>route.category?c.parentId===route.category:!c.parentId).filter(c=>categoryCount(c.id));return children.length?`<nav class="catalog-shortcuts" aria-label="${esc(t('categories'))}">${children.map(c=>{const p=categoryPhoto(c.id);return`<a href="${esc(href('catalog',catalogParams({category:c.id})))}" data-nav>${p?image(p,p.coverIndex||0,{alt:''}):icon('box')}<span>${esc(loc(c.name))}</span></a>`;}).join('')}</nav>`:'';}
function filterMarkup(category,sort,{mobile=false}={}){const route=currentRoute(),prefix=mobile?'mobile':'desktop';return`<div class="filters-content"><div class="filter-heading"><h2>${esc(t('categories'))}</h2><a class="link-button" href="${esc(href('catalog',{q:route.q}))}" data-nav>${esc(t('clear'))}</a></div><div class="category-filters"><a class="${category?'':'active'}" href="${esc(href('catalog',catalogParams({category:''})))}" data-nav>${esc(t('allProducts'))}<span>${count(distinctModels(catalog.products).length)}</span></a>${categoryNavigation(catalog.categories,category).filter(c=>categoryCount(c.id)).map(c=>`<a class="${c.depth?'child ':''}${c.id===category?'active':''}" data-category-depth="${Math.min(c.depth,5)}" href="${esc(href('catalog',catalogParams({category:c.id})))}" data-nav ${c.id===category?'aria-current="page"':''}>${esc(loc(c.name))}<span>${count(categoryCount(c.id))}</span></a>`).join('')}</div><form class="catalog-filter-form">${dimensionFilterMarkup(prefix,route)}<fieldset><legend>${esc(t('priceRange'))}</legend><div class="price-filter-inputs"><label for="${prefix}-min-price">${esc(t('minimumPrice'))}<input id="${prefix}-min-price" name="minPrice" type="number" min="0" max="999999999" step="0.01" inputmode="decimal" value="${esc(route.minPrice)}" placeholder="0"></label><label for="${prefix}-max-price">${esc(t('maximumPrice'))}<input id="${prefix}-max-price" name="maxPrice" type="number" min="0" max="999999999" step="0.01" inputmode="decimal" value="${esc(route.maxPrice)}" placeholder="${esc(t('noUpperLimit'))}"></label></div><p class="field-hint">TRY</p></fieldset><label class="filter-color" for="${prefix}-color"><strong>${esc(t('productColor'))}</strong><select id="${prefix}-color" name="color"><option value="">${esc(t('allColors'))}</option>${catalogColors().map(p=>`<option value="${esc(p.variantColor.tr)}" ${p.variantColor.tr===route.color?'selected':''}>${esc(loc(p.variantColor))}</option>`).join('')}</select></label>${mobile?`<label class="filter-color" for="mobile-filter-sort"><strong>${esc(t('sort'))}</strong><select id="mobile-filter-sort" name="sort">${sortOptions(sort)}</select></label>`:''}<button class="button button-dark" type="submit">${esc(t('applyFilters'))}</button></form></div>`;}
function dimensionFilterMarkup(prefix,route){return `<fieldset class="dimension-filter" id="${prefix}-space-filter"><legend>${esc(t('maximumDimensions'))}</legend><div class="dimension-inputs">${['Width','Height','Depth'].map(axis=>`<label for="${prefix}-max-${axis}">${esc(t('dimension'+axis))}<input type="text" inputmode="decimal" autocomplete="off" id="${prefix}-max-${axis}" name="max${axis}" value="${esc(route['max'+axis])}" placeholder="cm" pattern="[0-9]{1,5}([.,][0-9]{1,2})?"></label>`).join('')}</div><p class="field-hint">${esc(t('dimensionFilterHelp'))}</p></fieldset>`;}
