function positionProductSection(id){
 const section=document.getElementById(id);
 if(!section||!['product-information','product-specs','product-reviews','product-faq','product-questions','product-shelf-productSimilar','product-shelf-productComplementary'].includes(id))return;
 const header=$('.store-header'),headerOffset=Math.ceil((header?.getBoundingClientRect().height||0)+24);
 document.documentElement.style.setProperty('--store-header-offset',headerOffset+'px');
 const offset=headerOffset+(matchMedia('(min-width:1000px)').matches?($('.product-section-nav')?.getBoundingClientRect().height||0):0);
 section.tabIndex=-1;section.focus({preventScroll:true});
 window.scrollTo({left:0,top:Math.max(0,window.scrollY+section.getBoundingClientRect().top-offset),left:0,behavior:'instant'});
}
function navigateProductSection(id){
 const section=document.getElementById(id);
 if(!section||!['product-information','product-specs','product-reviews','product-faq','product-questions','product-shelf-productSimilar','product-shelf-productComplementary'].includes(id))return;
 initialProductSection='';saveView();viewRestoreToken++;pendingViewRestore=null;restoringView=null;
 activeViewKey=++nextViewKey;
 const url=new URL(location.href);url.hash=id;
 history.pushState({nodenoView:{key:activeViewKey,limit,scrollY:window.scrollY}},'',url.pathname+url.search+url.hash);
 const token=viewRestoreToken;
 requestAnimationFrame(()=>{
  if(token!==viewRestoreToken||!section.isConnected)return;
  positionProductSection(id);saveView();
 });
}

function productSpecOverview(p){
 if(!p.specs?.length)return '';
 const facts=summarizeSpecs(displaySpecs(p),locale).slice(0,4);
 return `<section class="product-spec-overview" aria-labelledby="product-highlights-title"><div class="spec-overview-heading"><h2 id="product-highlights-title">${esc(t('productHighlights'))}</h2><a class="specs-all-link" href="#product-specs" data-specs-link>${esc(t('viewAllSpecs'))}</a></div>${facts.length?`<dl class="product-quick-facts">${facts.map(fact=>`<div data-spec-fact="${esc(fact.key)}"><dt>${esc(fact.labelKey?t(fact.labelKey):fact.label)}</dt><dd dir="auto">${['width','height','depth'].includes(fact.key)?`<bdi dir="ltr">${esc(fact.value)}</bdi>`:esc(fact.value)}</dd></div>`).join('')}</dl>`:''}</section>`;
}
function productSpecifications(p){
 if(!p.specs?.length)return `<p>${esc(t('noSpecs'))}</p>`;
 const groups=groupSpecs(displaySpecs(p));
 const value=(row,list=false)=>{
  const raw=loc(row.spec.value),lines=raw.split(/\r?\n/).map(line=>line.trim()).filter(Boolean);
  const conciseList=list&&lines.every(line=>line.length<=180&&!/[:：]\s*$/u.test(line));
  return conciseList?`<ul class="spec-feature-list" data-spec-value>${lines.map(line=>`<li>${esc(line)}</li>`).join('\n')}</ul>`:`<div class="spec-prose" data-spec-value dir="auto">${esc(raw)}</div>`;
 };
 const attributes=groups.attributes.length?`<dl class="spec-attributes">${groups.attributes.map(row=>`<div data-spec-row="${row.index}"><dt>${esc(loc(row.spec.label))}</dt><dd data-spec-value dir="auto">${esc(loc(row.spec.value))}</dd></div>`).join('')}</dl>`:'';
 const definitions=[['features','specGroupFeatures'],['materials','specGroupMaterials'],['assembly','specGroupAssembly'],['care','specGroupCare'],['other','specGroupOther']].filter(([key])=>groups[key].length);
 return `${attributes}<div class="specification-groups">${definitions.map(([key,label],index)=>`<details class="spec-group" data-spec-group="${key}" ${index===0?'open':''}><summary><span>${esc(t(label))}</span><span class="spec-toggle" aria-hidden="true">${icon('plus')}${icon('minus')}</span></summary><div class="spec-group-content">${groups[key].map(row=>`<div class="spec-group-entry" data-spec-row="${row.index}"><h3 class="sr-only">${esc(loc(row.spec.label))}</h3>${value(row,key==='features')}</div>`).join('')}</div></details>`).join('')}</div>`;
}

