 return `<div class="social-signin-buttons">${['google','apple'].map(provider=>`<button type="button" class="social-signin social-${provider}" data-social-login="${provider}" ${socialStatus!=='ready'||!socialData?.providers?.[provider]?.ready?'disabled aria-disabled="true"':''} ${note?'aria-describedby="social-signin-note"':''}>${socialProviderIcon(provider)}<span>${esc(t(provider==='google'?'socialGoogle':'socialApple'))}</span></button>`).join('')}</div>${note?`<p id="social-signin-note" class="field-hint">${esc(t(note))}</p>`:''}${socialStatus==='error'?`<button type="button" class="link-button" data-action="reload-social">${esc(t('retry'))}</button>`:''}<div class="auth-divider"><span>${esc(t('socialDivider'))}</span></div>`;
