 return `<h2>${esc(t('socialConnectedAccounts'))}</h2><p class="subtle">${esc(t('socialConnectedIntro'))}</p>${socialNotice()}<div class="connected-provider-list">${['google','apple'].map(provider=>{const state=socialData?.providers?.[provider],ready=socialStatus==='ready'&&state?.ready;return `<div class="connected-provider"><div class="provider-name">${socialProviderIcon(provider)}<div><h3>${provider==='google'?'Google':'Apple'}</h3><span>${esc(t(state?(state.linked?'socialLinked':'socialNotLinked'):(socialStatus==='loading'?'socialLoading':'requestError')))}</span>${state?.linked?(state.emails||[]).map(email=>`<bdi dir="ltr">${esc(email)}</bdi>`).join(''):''}</div></div><div class="provider-actions">${state?.linked?`${session.user?.hasPassword===false?`<button type="button" class="link-button" data-social-reauth="${provider}" ${ready?'':'disabled'}>${esc(t('socialReauthenticate'))}</button>`:''}<button type="button" class="link-button" data-social-unlink="${provider}">${esc(t('socialUnlink'))}</button>`:`<button type="button" class="button" data-social-link="${provider}" ${ready?'':'disabled'}>${esc(t('socialLink'))}</button>`}</div></div>`;}).join('')}</div>${socialStatus==='loading'?`<p class="field-hint" role="status">${esc(t('socialLoading'))}</p>`:!['google','apple'].some(provider=>socialData?.providers?.[provider]?.ready)?`<p class="field-hint">${esc(t('socialUnavailable'))}</p>`:''}${socialStatus==='error'?`<button type="button" class="link-button" data-action="reload-social">${esc(t('retry'))}</button>`:''}${merge?`<section class="social-merge-proposal"><h3>${esc(t('socialMergeTitle'))}</h3><bdi dir="ltr">${esc(merge.email)}</bdi><p>${esc(t('socialMergeBody'))}</p><div><button type="button" class="button button-dark" data-action="social-merge">${esc(t('socialMergeConfirm'))}</button><button type="button" class="button" data-action="social-merge-cancel">${esc(t('socialMergeCancel'))}</button></div><p id="social-merge-error" class="form-status" role="alert"></p></section>`:''}`;
