function productFaqMarkup(p){
 const groups=groupSpecs(displaySpecs(p)),entries=[];
 for(const [group,title]of [['assembly','faqAssembly'],['care','faqCare']])if(groups[group].length)entries.push([title,groups[group].map(row=>loc(row.spec.value)).join('\n\n')]);
 const packaging=displaySpecs(p).find(s=>/koli|ambalaj/iu.test(s.label.tr));if(packaging)entries.push(['faqPackaging',loc(packaging.value)]);
 entries.push(['faqDelivery',t('shippingBody')+'\n\n'+t('returnsBody')],['faqSupport',t('faqSupportBody')]);
 return `<section class="detail-section product-faq" id="product-faq"><h2>${esc(t('productFaq'))}</h2>${entries.map(([title,answer])=>`<details><summary>${esc(t(title))}<span class="spec-toggle" aria-hidden="true">${icon('plus')}${icon('minus')}</span></summary><div><p>${esc(answer)}</p>${title==='faqSupport'?contactMarkup():''}</div></details>`).join('')}</section>`;
}
function productCollections(p){
 const roots=new Set(p.categoryIds.filter(id=>!categoryById(id)?.parentId));
 const categories=catalog.categories.filter(c=>c.parentId&&roots.has(c.parentId)&&categoryCount(c.id)>1).slice(0,4);
 if(!categories.length)return '';
 return `<section class="detail-section product-collections" id="product-collections"><h2>${esc(t('productCollections'))}</h2><div class="collection-row">${categories.map(category=>{const products=distinctModels(catalog.products.filter(v=>v.categoryIds.includes(category.id))).slice(0,3);return `<a class="collection-card" href="${esc(href('catalog',{category:category.id}))}" data-nav><div class="collection-mosaic">${products.map((v,i)=>`<span class="collection-photo collection-photo-${i}">${image(v,v.coverIndex||0,{alt:''})}</span>`).join('')}</div><h3>${esc(loc(category.name))}</h3><span>${esc(t('viewCollection'))}</span></a>`;}).join('')}</div></section>`;
}
function productExtraSections(p,ask){
 const suggestions=productSuggestions(p,catalog.products,catalog.categories,recent);if(recommendedIds.length)suggestions.similar=distinctModels([...recommendedIds.map(byId).filter(v=>v&&(v.modelId||v.id)!==(p.modelId||p.id)),...suggestions.similar]).slice(0,12);
 // The existing ask URL already has a body. Replace that parameter rather than
 // duplicating it, keeping the selected product attached to the question.
 const questionLink=topic=>{if(!ask)return `<button class="question-topic" data-panel="contact">${esc(t(topic))}</button>`;const url=new URL(ask);url.searchParams.set('body',p.code+'\n'+productName(p)+'\n'+t(topic)+'\n'+new URL(productHref(p.id),location.origin).href);return `<a class="question-topic" href="${esc(url.href)}">${esc(t(topic))}</a>`;};
 const hasDimensions=summarizeSpecs(displaySpecs(p),locale).some(f=>['width','dimensions'].includes(f.key));
 return `${renderPaintRecommendations(p,catalog.products,locale,{esc,renderCard:productCard})}<section class="detail-section product-questions" id="product-questions"><div class="section-heading"><h2>${esc(t('productQuestions'))}</h2>${questionLink('questionAsk')}</div><p class="subtle">${esc(t('questionIntro'))}</p><div class="question-topics">${questionLink('questionSizes')}${questionLink(p.paintUse?'questionAsk':'questionAssembly')}</div></section><section class="detail-section" id="product-reviews"><h2>${esc(t('reviews'))}</h2><p class="subtle">${esc(t('noReviews'))}</p></section><section class="detail-section product-guidance"><h2>${esc(t('productGuidance'))}</h2><div class="guidance-grid">${hasDimensions?`<a href="#product-specs" data-specs-link><span>${icon('box')}</span><div><h3>${esc(t('checkDimensions'))}</h3><p>${esc(t('checkDimensionsBody'))}</p></div></a>`:''}<a href="#product-faq" data-specs-link><span>${icon('box')}</span><div><h3>${esc(t(p.paintUse?'viewAllSpecs':'assemblyCare'))}</h3><p>${esc(p.paintUse?loc(p.paintGuide):t('assemblyCareBody'))}</p></div></a></div></section>${productFaqMarkup(p)}<section class="detail-section product-save-section"><button data-save="${esc(p.id)}" class="save-product-row ${saved.has(p.id)?'saved':''}" aria-pressed="${saved.has(p.id)}">${icon('heart')}<span>${esc(saved.has(p.id)?t('removeFavorite'):t('saveProduct'))}</span></button></section>${productShelf('productSimilar',suggestions.similar)}${productCollections(p)}${productShelf('productComplementary',suggestions.complementary)}${productShelf('recent',suggestions.recent)}<section class="detail-section product-feedback">${questionLink('shareFeedback')}</section>`;
}
function buyProduct(id){
 if(isDoor(byId(id))||isCabinetFront(byId(id))){if(addCart(id,detailQuantity)!==false)navigate(href('cart'));return;}
 if(selectionsBlocked()){toast(t('loading'));return;}
 const item=cart.find(row=>row.id===id);if(!item&&cart.length>=100){toast(t('cartLimit'));return;}
 if(!byId(id))return;if(item)item.quantity=detailQuantity;else cart.push({id,quantity:detailQuantity});
 selected=new Set([id]);persistSelections();updateCounts();navigate(href('checkout'));
}
function centerSelectedColor(){const option=$('.color-option[aria-current]');if(!option)return;const strip=option.parentElement;strip.scrollLeft+=option.getBoundingClientRect().left-strip.getBoundingClientRect().left-(strip.clientWidth-option.clientWidth)/2;}
function displaySpecs(p){return p.colorReviewPending?p.specs.map(s=>/ren[kg]/iu.test(s.label.tr)?{...s,value:Object.fromEntries(locales.map(lang=>[lang,shopTranslate('colorPending',lang)]))}:s):p.specs;}
function renderColorOptions(p){const variants=variantsOf(p);if(variants.length<2)return'';return `<fieldset class="color-options"><legend>${esc(t('productColor'))}: <strong>${esc(loc(p.variantColor))}</strong><span>${count(variants.length)} ${esc(t('colorOptions'))}</span></legend><div class="color-option-strip">${variants.map(v=>`<a class="color-option" href="${esc(productHref(v.id))}" data-variant="${esc(v.id)}" ${v.id===p.id?'aria-current="true"':''} title="${esc(loc(v.variantColor))}">${image(v,v.coverIndex||0,{alt:''})}<span>${esc(loc(v.variantColor))}</span></a>`).join('')}</div></fieldset>`;}
function selectVariant(id){const current=byId(currentRoute().product),next=byId(id);if(!current||!next||current.modelId!==next.modelId||current.id===next.id)return;const quantity=clamp(detailQuantity,next),y=window.scrollY;navigate(productHref(next.id),{focus:false});detailQuantity=quantity;if($('#detail-quantity'))$('#detail-quantity').value=String(quantity);window.scrollTo({left:0,top:y,behavior:'instant'});const selected=$(`[data-variant="${CSS.escape(id)}"]`);selected?.focus({preventScroll:true});centerSelectedColor();saveView();}
const supplierDetailRequests=new WeakSet(),supplierDetailErrors=new WeakSet();
function loadSupplierDetails(p,{retry=false}={}){
 if(!isSupplierProduct(p)||!p.supplierDetailsHash||p.supplierDetailsLoaded||supplierDetailRequests.has(p)||(!retry&&supplierDetailErrors.has(p)))return;
 supplierDetailErrors.delete(p);supplierDetailRequests.add(p);
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);
 fetch('/api/supplier-products/'+encodeURIComponent(p.id)+'?v='+encodeURIComponent(p.supplierDetailsHash),{signal:controller.signal}).then(async response=>{
  if(!response.ok)throw new Error('supplier_details');const data=await response.json();
  if(data.id!==p.id||data.sha256!==p.supplierDetailsHash||!baseLocales.every(lang=>typeof data.description?.[lang]==='string'&&data.description[lang]))throw new Error('supplier_details');
  let preparedLocale;do{preparedLocale=locale;await ensureLocaleData(data.description,preparedLocale);}while(preparedLocale!==locale);
  localizeDataTree(data,locale);
  p.description=data.description;p.supplierDetailsLoaded=true;
 }).catch(()=>{supplierDetailErrors.add(p);}).finally(()=>{
  clearTimeout(timeout);supplierDetailRequests.delete(p);
  if(currentRoute().product===p.id&&byId(p.id)===p)renderPage({focus:false});
 });
}
function renderProduct(){const p=byId(currentRoute().product);if(!p)return`<div class="wrap">${empty('resultsNone','resultsHint')}</div>`;loadSupplierDetails(p);if(activeProduct!==p.id){activeProduct=p.id;gallery=p.coverIndex||0;detailQuantity=isDoor(p)?(doorUI.country()==='TR'?5:10):isSupplierProduct(p)?supplierPolicy(p).minimum:1;if(optionalPersonalizationAllowed()){recent=[p.id,...recent.filter(id=>id!==p.id)].slice(0,20);optionalPersonalizationAllowed()&&write('nodeno.recent.v1',recent);}}const cats=p.categoryIds.map(categoryById).filter(Boolean),images=p.images||[];gallery=Math.max(0,Math.min(gallery,Math.max(0,images.length-1)));const email=contactLinks(config).find(link=>link.kind==='email'),ask=email?`${email.href}?subject=${encodeURIComponent(t('contactSubject')+': '+p.code)}&body=${encodeURIComponent(p.code+'\n'+productName(p)+'\n'+new URL(productHref(p.id),location.origin).href)}`:null;return`<div class="wrap product-page"><nav class="breadcrumb" aria-label="${esc(t('category'))}">${navLink('home','home')}<span class="breadcrumb-separator" aria-hidden="true"></span>${cats[0]?`<a href="${esc(href('catalog',{category:cats[0].id}))}" data-nav>${esc(loc(cats[0].name))}</a><span class="breadcrumb-separator" aria-hidden="true"></span>`:''}<bdi dir="ltr">${esc(p.code)}</bdi></nav><div class="product-detail-layout"><section class="product-gallery" aria-label="${esc(t('image'))}"><div class="gallery-main"><div id="gallery-viewport" class="gallery-viewport" tabindex="0" role="region" aria-label="${esc(t('productPhotos'))}" dir="ltr">${images.length?images.map((_,i)=>`<button type="button" class="gallery-slide" data-gallery-slide="${i}" data-action="zoom" aria-label="${esc(t('zoom'))} ${count(i+1)}">${image(p,i,{lazy:i!==gallery})}</button>`).join(''):image(p,0,{lazy:false})}</div>${images.length?`<button type="button" class="zoom-hint" data-action="zoom">${icon('search')} ${esc(t('zoom'))}</button>`:''}<button type="button" class="product-photo-save ${saved.has(p.id)?'saved':''}" data-save="${esc(p.id)}" aria-label="${esc(t('favorites'))}" aria-pressed="${saved.has(p.id)}">${icon('heart')}</button></div>${images.length>1?`<div class="gallery-controls"><button class="icon-button" data-gallery-step="-1" ${gallery===0?'disabled':''} aria-label="${esc(t('prev'))}">${icon('previous')}</button><div class="gallery-center"><div class="gallery-points" dir="ltr">${images.map((_,i)=>`<button type="button" class="gallery-point" data-gallery-point="${i}" aria-pressed="${i===gallery}" aria-label="${esc(t('image'))} ${count(i+1)}"><span></span></button>`).join('')}</div><bdi id="gallery-counter" dir="ltr" role="status" aria-live="polite" aria-atomic="true">${count(gallery+1)} / ${count(images.length)}</bdi></div><button class="icon-button" data-gallery-step="1" ${gallery===images.length-1?'disabled':''} aria-label="${esc(t('next'))}">${icon('next')}</button></div><div class="gallery-thumbs">${images.map((_,i)=>`<button class="gallery-thumb" data-gallery="${i}" aria-pressed="${i===gallery}" aria-label="${esc(t('image'))} ${count(i+1)}">${image(p,i,{alt:''})}</button>`).join('')}</div>`:''}</section><div class="product-purchase">
 <header class="product-title-block"><div class="product-heading"><a class="product-brand" href="${esc(href('catalog'))}" data-nav translate="no">${esc(p.productBrand||'NODENO')}</a><h1 id="product-title" tabindex="-1">${esc(productName(p))}</h1></div><div class="product-identifiers"><button class="product-code link-button" data-copy-code="${esc(p.id)}">${esc(t('code'))}: <bdi dir="ltr" translate="no">${esc(p.code)}</bdi></button><a href="#product-specs" data-specs-link>${esc(t('viewAllSpecs'))}</a></div></header>
 <div class="product-price-block"><p class="detail-price">${isDoor(p)?`<small class="measurement-base-caption">${esc(measurementsUI.t('baseRate'))}</small>`:''}${priceMarkup(p,'price-value')}</p>${p.scopeNote?`<p class="product-scope-note" role="note">${esc(loc(p.scopeNote))}</p>`:''}</div>
 ${isSupplierProduct(p)?supplierVariants(p,variantsOf(p),locale,{esc,href:productHref}):isDoor(p)||isCabinetFront(p)?doorUI.variants(p):renderColorOptions(p)}
 ${isCabinetFront(p)||isDoor(p)?measurementsUI.configuration(p):p.productType==='cabinet-profile'?`<p class="door-price-basis">${esc(frontUI.t('profile'))}</p>`:p.productType==='door-profile'?`<p class="door-price-basis">${esc(doorUI.t('profile'))}</p>`:''}
 <div class="purchase-choice-row">${!isDoor(p)&&!isCabinetFront(p)?`<div class="purchase-controls"><label for="detail-quantity">${esc(isSupplierProduct(p)?supplierQuantityLabel(p,locale):t('quantity'))}</label>${quantityMarkup(p.id,detailQuantity,{detail:true})}</div>`:''}<div class="product-buy-actions"><button type="button" class="button button-buy-now" data-product-buy="${esc(p.id)}" ${p.variationSelectionRequired?'disabled':''}>${esc(t('buyNow'))}</button><button class="button button-dark" data-detail-add="${esc(p.id)}" ${p.variationSelectionRequired?'disabled':''}>${icon('cart')}${esc(t('add'))}</button><button class="button save-detail ${saved.has(p.id)?'saved':''}" data-save="${esc(p.id)}" aria-pressed="${saved.has(p.id)}" aria-label="${esc(t('favorites'))}">${icon('heart')}<span>${esc(t('favorites'))}</span></button></div></div>
 <p class="product-payment-note" role="note">${esc(t('productPaymentPending'))}</p>
 ${productSpecOverview(p)}
 ${experience?.productTools(p)||''}
 <div class="delivery-preview"><span>${icon('box')}</span><div><strong>${esc(t('shipping'))}</strong><p>${esc(t('deliveryGuide'))}</p>${navLink('shipping','deliveryDetails','text-link')}</div></div>
 <div class="detail-secondary"><button data-share="${esc(p.id)}">${icon('share')}${esc(t('share'))}</button>${ask?`<a href="${esc(ask)}">${esc(t('askProduct'))}</a>`:`<button data-panel="contact">${esc(t('askProduct'))}</button>`}</div>
 </div>${productServicePanel(p)}</div><nav class="product-section-nav"><a href="#product-information">${esc(t('details'))}</a><a href="#product-specs">${esc(t('specifications'))}</a><a href="#product-reviews">${esc(t('reviews'))}</a><a href="${esc(href('help',{section:'returns'}))}" data-nav>${esc(t('returns'))}</a></nav><section class="detail-section" id="product-information"><h2>${esc(t('details'))}</h2>${productAboutMarkup(p)}</section><section class="detail-section product-specifications" id="product-specs" tabindex="-1" aria-labelledby="product-specifications-title"><h2 id="product-specifications-title">${esc(t('specifications'))}</h2>${productSpecifications(p)}</section>${productExtraSections(p,ask)}<div class="mobile-purchase"><span>${isDoor(p)||isCabinetFront(p)?measurementsUI.purchaseMarkup(p):priceMarkup(p,'price-value')}</span><button type="button" class="button button-buy-now" data-product-buy="${esc(p.id)}" ${p.variationSelectionRequired?'disabled':''}>${esc(t('buyNow'))}</button><button class="button button-dark" data-detail-add="${esc(p.id)}" ${p.variationSelectionRequired?'disabled':''}>${icon('cart')}${esc(t('add'))}</button></div></div>`;}
function selectedCart(){return cart.filter(item=>selected.has(cartLineKey(item)));}
function cartLineProduct(p,item){if(isCabinetFront(p)){const price=frontPrice(p,item.options,item.quantity);return {...p,salePriceMinor:price.unitPriceMinor,salePrice:price.unitPriceMinor===null?null:price.unitPriceMinor/100,calculatedLineTotal:price.lineTotalMinor,configuredFront:true};}if(!isDoor(p))return p;const price=doorPrice(p,item.options||{}),copy={...p,salePriceMinor:price.unitPriceMinor,salePrice:price.unitPriceMinor===null?null:price.unitPriceMinor/100};delete copy.previousPriceMinor;delete copy.discountPercent;return copy;}
function basketSummary(){const chosen=selectedCart();return `<aside class="basket-summary"><h2>${esc(t('cartSummary'))}</h2><div data-payment-summary>${basketMoneySummary()}</div>${doorUI.cartSummary()}${chosen.length&&doorUI.status().eligible?navLink('checkout','guestContinueCheckout','button button-dark'):`<button class="button button-dark" disabled>${esc(t('guestContinueCheckout'))}</button>`}${config.checkoutEnabled?'':`<p class="catalogue-notice">${esc(t('checkoutClosed'))}</p>`}</aside>`;}

function renderCart(){return`<div class="wrap basket-page">${pageHeading('cart',navLink('catalog','browse','text-link'))}<div data-sync></div>${cart.length?`<div class="basket-layout"><div><div class="basket-select"><label><input type="checkbox" id="select-all" ${cart.every(item=>selected.has(cartLineKey(item)))?'checked':''}>${esc(t('selectAll'))} (${count(cart.length)})</label><button class="link-button" data-action="clear-cart">${esc(t('clearCart'))}</button></div><div class="basket-items">${cart.map(item=>{const source=byId(item.id),p=cartLineProduct(source,item);return`<article class="basket-item" data-selected="${selected.has(cartLineKey(item))}"><label class="item-select"><span class="sr-only">${esc(t('selectItem'))}: ${esc(productName(p))}</span><input type="checkbox" data-select="${esc(cartLineKey(item))}" ${selected.has(cartLineKey(item))?'checked':''}></label>${productLink(item.id,image(p),'basket-photo')}<div class="basket-product"><bdi class="product-code" dir="ltr">${esc(p.code)}</bdi><h2>${productLink(item.id,esc(productName(p)))}</h2>${p.colorReviewPending?`<p class="basket-color">${esc(t('colorPending'))}</p>`:''}${isSupplierProduct(p)&&p.variantLabel&&!p.variationSelectionRequired?`<p class="basket-color">${esc(loc(p.variantLabel))}</p>`:''}${!isSupplierProduct(p)&&p.variantColor?`<p class="basket-color">${esc(t('productColor'))}: ${esc(loc(p.variantColor))}</p>`:''}${isCabinetFront(p)?frontUI.lineDescription(source,item):isDoor(p)?doorUI.lineDescription(source,item):(!isSupplierProduct(p)?experience?.cartVariantButton(p):'')||''}<p class="basket-unit-price">${unitPriceMinor(p)===null?priceMarkup(p):`<span>${esc(t('unitPrice'))}</span> ${priceMarkup(p)}`}</p><div class="basket-item-actions"><button class="link-button" data-move="${esc(cartLineKey(item))}">${esc(t('moveFavorites'))}</button><button class="link-button" data-remove="${esc(cartLineKey(item))}">${esc(t('remove'))}</button></div></div><div class="basket-item-end">${quantityMarkup(cartLineKey(item),item.quantity,{product:p})}${linePriceMarkup(p,item.quantity)}</div></article>`;}).join('')}</div>${doorUI.requestForm()}</div>${basketSummary()}</div>${cartSuggestions()}`:empty('emptyCart','emptyCartBody','cart')}</div>`;}
function accountGate(){if(sessionStatus==='loading')return`<div class="panel loading-state" role="status">${esc(t('loading'))}</div>`;if(sessionStatus==='error')return`<div class="panel">${empty('errorTitle','sessionUnavailable','user')}<button class="button" data-action="retry-account">${esc(t('retry'))}</button></div>`;if(!session.user)return`<div class="panel account-gate">${icon('user')}<h2>${esc(t('loginRequired'))}</h2><p>${esc(t('accountIntro'))}</p>${navLink('login','login','button button-dark')}${navLink('register','register','button')}</div>`;return'';}
function accountLayout(key,content){return`<div class="wrap account-page">${pageHeading(key)}<div class="account-layout"><aside class="account-sidebar"><div class="account-identity">${icon('user')}<strong>${esc(session.user?.name||t('account'))}</strong></div><nav>${[['orders','box'],['account','user'],['addresses','pin'],['favorites','heart'],['shipping','box'],['help','menu']].map(([page,ico])=>`<a href="${esc(href(page))}" data-nav ${(currentRoute().page===page||page==='categories'&&currentRoute().page==='catalog')?'aria-current="page"':''}>${icon(ico)}${esc(t(page==='account'?'profile':page))}</a>`).join('')}${session.user?`<button data-action="logout">${esc(t('logout'))}</button>`:''}</nav></aside><div class="account-content">${accountGate()||content}</div></div></div>`;}
function field(name,key,{value='',type='text',required=true,autocomplete='',max=160,min=0,readonly=false}={}){return`<label class="form-field" for="field-${name}"><span>${esc(t(key))}</span><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${readonly?'readonly':''} ${autocomplete?`autocomplete="${autocomplete}"`:''} maxlength="${max}" ${min?`minlength="${min}"`:''}></label>`;}
function formStatus(){return`<p class="form-status" role="alert">${esc(accountError)}</p>`;}
function renderAuth(register=false){const gate=sessionStatus==='loading'||sessionStatus==='error'?accountGate():'';if(gate)return`<div class="wrap auth-page">${pageHeading(register?'register':'login')}${gate}</div>`;if(session.user)return accountLayout('account',`<div class="panel"><p>${esc(t('registered'))}</p>${navLink('account','profile','button button-dark')}</div>`);return`<div class="wrap auth-page"><section class="auth-card"><a class="auth-brand" href="${href()}" data-nav><img src="/assets/brand/logo-horizontal.svg?v=social-keywords-20261113-v6" width="1600" height="360" alt="NODENO"></a><h1 tabindex="-1">${esc(t(register?'register':'login'))}</h1><p class="subtle">${esc(t('accountIntro'))}</p>${socialNotice()}<div id="social-auth-options" aria-busy="${socialStatus==='loading'}">${socialOptionsMarkup()}</div><form id="${register?'register':'login'}-form">${register?field('name','name',{autocomplete:'name',max:100}):''}${field('email','email',{type:'email',autocomplete:'email',max:254})}${field('password','password',{type:'password',autocomplete:register?'new-password':'current-password',min:register?12:1,max:72})}${register?`<p class="field-hint">${esc(t('passwordRule'))}</p>${field('repeatPassword','repeatPassword',{type:'password',autocomplete:'new-password',min:12,max:72})}<p><a href="/legal/kvkk?lang=${locale}" target="_blank" rel="noopener">${esc(legalCopy(locale).kvkk)}</a></p><label class="consent"><input name="membership" type="checkbox" required><span><a href="/legal/membership?lang=${locale}" target="_blank" rel="noopener">${esc(legalCopy(locale).membership)}</a></span></label>`:''}${formStatus()}<button class="button button-dark" type="submit">${esc(t(register?'register':'login'))}</button></form>${register?'':`<button class="link-button forgot-password" data-action="password-reset">${esc(t('forgotPassword'))}</button>`}<p class="auth-switch">${esc(t(register?'haveAccount':'noAccount'))} ${navLink(register?'login':'register',register?'login':'register','link-button',{next:new URLSearchParams(location.search).get('next')==='checkout'?'checkout':''})}</p></section></div>`;}
function renderProfile(){if(!session.user)return accountLayout('account','');return accountLayout('account',`<form class="panel profile-form" id="profile-form"><h2>${esc(t('profile'))}</h2><div class="form-grid">${field('name','name',{value:session.user.name,autocomplete:'name',max:100})}${field('email','email',{value:session.user.email,type:'email',readonly:true})}</div><p class="subtle">${esc(t(session.user.emailVerified?'emailVerified':'emailNotVerified'))}</p>${formStatus()}<button class="button button-dark">${esc(t('saveChanges'))}</button></form><section class="panel connected-accounts" id="connected-accounts" aria-busy="${socialStatus==='loading'}">${connectedAccountsMarkup()}</section><form class="panel password-form" id="password-form"><h2>${esc(t(session.user.hasPassword===false?'socialSetPassword':'password'))}</h2>${session.user.hasPassword===false?`<p class="subtle">${esc(t('socialPasswordBody'))}</p>`:''}<div class="form-grid">${session.user.hasPassword!==false?field('currentPassword','currentPassword',{type:'password',autocomplete:'current-password',max:72}):''}${field('password','newPassword',{type:'password',autocomplete:'new-password',min:12,max:72})}${field('repeatPassword','repeatPassword',{type:'password',autocomplete:'new-password',min:12,max:72})}</div><p class="field-hint">${esc(t('passwordRule'))}</p><p class="form-status" role="alert"></p><button class="button button-dark">${esc(t('saveChanges'))}</button></form>${deleteAccountForm()}`);}
function addressCard(address,{choose=false}={}){return`<article class="address-card ${chosenAddress===address.id?'chosen':''}"><div class="address-card-title"><h3>${esc(address.label)}</h3>${address.isDefault?`<span class="tag">${esc(t('default'))}</span>`:''}</div><p><strong>${esc(address.name)}</strong></p><p><bdi dir="ltr">${esc(address.phone)}</bdi></p><p>${esc(address.line1)}${address.line2?'<br>'+esc(address.line2):''}<br>${esc(address.district)} / ${esc(address.city)}<br>${esc(address.postalCode||'')} ${esc(address.country)}</p>${choose?`<label class="address-choice"><input type="radio" name="address-choice" value="${esc(address.id)}" ${chosenAddress===address.id?'checked':''}>${esc(t('chooseAddress'))}</label>`:`<div class="address-actions"><button class="link-button" data-edit-address="${esc(address.id)}">${esc(t('edit'))}</button>${!address.isDefault?`<button class="link-button" data-default-address="${esc(address.id)}">${esc(t('setDefault'))}</button>`:''}<button class="link-button" data-delete-address="${esc(address.id)}">${esc(t('delete'))}</button></div>`}</article>`;}
function addressForm(){const a=editingAddress||{};return`<form id="address-form" class="panel" data-draft-key="${esc(`${sessionEpoch}:${session.user?.id||''}:${a.id||''}`)}"><h2>${esc(t(a.id?'editAddress':'newAddress'))}</h2><div class="form-grid">${field('label','addressLabel',{value:a.label,max:80})}${field('name','recipient',{value:a.name||session.user?.name,autocomplete:'name',max:120})}${field('phone','telephone',{value:a.phone,type:'tel',autocomplete:'tel',max:30})}${field('country','country',{value:a.country,autocomplete:'country-name',max:80})}${field('city','city',{value:a.city,autocomplete:'address-level1',max:100})}${field('district','district',{value:a.district,autocomplete:'address-level2',max:100})}${field('postalCode','postalCode',{value:a.postalCode,autocomplete:'postal-code',required:false,max:20})}${field('line1','line1',{value:a.line1,autocomplete:'address-line1',max:400})}${field('line2','line2',{value:a.line2,autocomplete:'address-line2',required:false,max:250})}</div><label class="checkbox-label"><input name="isDefault" type="checkbox" ${a.isDefault?'checked':''}>${esc(t('defaultAddress'))}</label><p class="form-status" role="alert"></p><div class="form-actions"><button class="button button-dark">${esc(t('save'))}</button><button class="button" type="button" data-action="cancel-address">${esc(t('cancel'))}</button></div></form>`;}
function renderAddresses(){return accountLayout('addresses',`<div class="panel-heading"><h2>${esc(t('addresses'))}</h2><button class="button button-dark" data-action="new-address">${esc(t('newAddress'))}</button></div>${addressError?`<p class="error" role="alert">${esc(addressError)} <button class="link-button" data-action="reload-addresses">${esc(t('retry'))}</button></p>`:''}${addresses===null?`<p role="status">${esc(t('addressLoading'))}</p>`:addresses.length?`<div class="address-grid">${addresses.map(a=>addressCard(a)).join('')}</div>`:`<div class="panel"><p>${esc(t('noAddresses'))}</p></div>`}${addressFormOpen?addressForm():''}`);}
function orderDate(value){return formatDate(value);}
function statusLabel(value){if(['paid','refunded','partially_refunded'].includes(value))return paymentText(locale,value==='partially_refunded'?'partiallyRefunded':value);const labels={pending:'statusPending',processing:'statusProcessing',shipped:'statusShipped',delivered:'statusDelivered',cancelled:'statusCancelled',returned:'statusReturned'};return labels[value]?t(labels[value]):'';}
function trackingLink(value){try{const url=new URL(value);return url.protocol==='https:'&&!url.username&&!url.password?url.href:null;}catch{return null;}}
function shipmentMarkup(shipment){const link=trackingLink(shipment.trackingUrl||shipment.tracking_url),code=shipment.trackingNumber||shipment.tracking_number||shipment.trackingCode||'',carrier=shipment.carrier||'',status=statusLabel(shipment.status);return `<article class="shipment-card">${status?`<p><strong>${esc(t('shipmentStatus'))}:</strong> ${esc(status)}</p>`:''}${carrier?`<p>${esc(t('carrier'))}: ${esc(carrier)}</p>`:''}${code?`<p>${esc(t('trackingCode'))}: <bdi dir="ltr">${esc(code)}</bdi></p>`:''}${link?`<a class="text-link" href="${esc(link)}" target="_blank" rel="noopener noreferrer">${esc(t('tracking'))}<span class="sr-only">${esc(t('newWindow'))}</span></a>`:''}</article>`;}
