  if(currentRoute().product!==id){navigate(productHref(id));return false;}
  const lines=measurementsUI.validate(p);if(!lines)return false;
  try{const next=mergeMeasurementCart(cart,lines);cart=next;for(const line of lines)selected.add(cartLineKey(line));guestCheckout={details:guestCheckout.details,review:null};saveCheckoutDraft(guestCheckout,session.user?.id||'guest');selectionsChanged();insights?.event('cart',id);toast(t('added'));return true;}
  catch{toast(measurementsUI.t('limit'));return false;}
